function curry(fn) {
  const arity = fn.length;
  return function curried(...args) {
    if (args.length >= arity) {
      return fn.apply(this, args.slice(0, arity));
    }
    return function(...next) {
      return curried.apply(this, args.concat(next));
    };
  };
}
