function creerBST() {
  let root = null;

  function insertNode(node, val) {
    if (node === null) return { val, left: null, right: null };
    if (val < node.val) node.left = insertNode(node.left, val);
    else if (val > node.val) node.right = insertNode(node.right, val);
    return node;
